kroppar_per_varv:
xDriftsklar := EMG_OK AND AIR_OK;
xStopp := NOT EMG_OK OR NOT AIR_OK;
tmrAck(IN := (steg = 1), PT := T#2s);
tmrDone(IN := (steg = 2), PT := T#2s);
tmrHamta(IN := (steg <> 0), PT := T#5s);
xLarm := tmrAck.Q OR tmrDone.Q OR tmrHamta.Q;
IF xStopp THEN
steg := 0;
ELSE
CASE steg OF
0:
IF xDriftsklar AND NOT ST300_PEC_RCV AND NOT ST300_HS_ACK AND NOT ST300_HS_DONE AND NOT ST290_GRP_OPENED AND NOT xLarm THEN
steg := 1;
END_IF;
1:
IF ST300_HS_ACK AND NOT ST300_PEC_RCV AND xDriftsklar THEN
steg := 2;
END_IF;
2:
IF ST290_GRP_OPENED AND ST300_HS_DONE AND ST300_PEC_RCV THEN
steg := 3;
END_IF;
3:
IF NOT ST300_HS_ACK AND NOT ST300_HS_DONE THEN
steg := 0;
END_IF;
ELSE
steg := 0;
END_CASE;
END_IF;
ST290_HS_REQ := ((steg = 1) OR (steg = 2) OR (steg = 3)) AND xDriftsklar;
ST290_HS_RST := (steg = 3) AND xDriftsklar;
ST290_GRP_OPEN := (((steg = 2) AND ST300_HS_ACK) OR (steg = 3)) AND xDriftsklar;
ST300_CNV_RUN := (steg = 0) AND ST300_PEC_RCV AND NOT ST290_GRP_OPENED AND xDriftsklar AND NOT xLarm;
